INSERT INTO "documents" VALUES('practice_tasks','practice-04dcb662-04b2-4ff7-bdea-00b860709358:0','{"id": "practice-04dcb662-04b2-4ff7-bdea-00b860709358:0", "concept_id": "paths", "question": "Two paths have amplitudes $1/2$ and $e^{i\\phi}/2$.", "origin": "self_created", "source_refs": [], "status": "attempted", "history": [{"action": "hint", "feedback": "Expand $|z|^2 = z^* z$ first."}, {"action": "assess", "feedback": "Part (a) is right; check the sign in (b).", "outcome": "needs_work", "parts": ["correct", "not_yet"], "evidence_id": "practice-evidence:practice-690186b4-a847-4b3d-a368-59acb60e098d", "kind": "needs_work", "answer": "(a) P = (1 + cos phi)/2. (b) phi = 0."}], "created_at": 1795105751.480708, "parts": [{"label": "(a)", "text": "Find $P(\\phi)$."}, {"label": "(b)", "text": "When is it zero?"}]}');
