: "Superposition", "concept_ids": ["paths", "states"]}, {"id": "measurement", "title": "Measurement", "concept_ids": ["outcomes"]}], "learner_profile": {"goal": "Understand interference and measurement", "depth": "standard", "prerequisites": [{"topic": "Complex numbers", "level": "some", "check": "Multiplied two complex numbers"}], "focus": "Problem solving"}, "course_memory": {"preferences": ["Worked example before each new idea"], "taught_terms": [{"term": "amplitude", "concept_id": "paths"}, {"term": "interference term", "concept_id": "paths"}]}, "widgets": ["plot"], "branch": {"id": "cross-term", "question": "Why is the cross term 2 Re(a* b)?", "selection": "a complex amplitude", "anchor": {"scroll_y": 240}, "restore_point": {"concept_id": "paths", "goal": "Predict interference", "next_step": "Start the lesson", "progress": ""}, "main_turn_id": "step:44a01d0f-d419-48cc-8a06-d32a19f065f1", "selected_turn_id": "c7865339-0a1a-45cb-bb1e-e8a42d53eed6", "selected_lecture": {"id": "c7865339-0a1a-45cb-bb1e-e8a42d53eed6", "concept_id": "paths", "title": "Adding path amplitudes", "status": "completed", "text": "## Path amplitudes\n\nEach path carries a complex amplitude $a$ or $b$.\n<course-memory>{\"entries\": [{\"kind\": \"taught_term\", \"text\": \"amplitude\"}, {\"kind\": \"preference\", \"text\": \"Short steps with one formula each\"}], \"cleared\": []}</course-memory>\n<lesson-step>{\"title\": \"Path amplitudes\", \"remaining\": [{\"title\": \"Adding amplitudes\"}], \"check\": {\"idea\": \"What does a path carry?\", \"question\": \"What does a path carry?\", \"correct\": 0, \"options\": [{\"text\": \"A complex amplitude\", \"explanation\": \"Each path contributes an amplitude.\"}, {\"text\": \"A probability\", \"explanation\": \"Probabilities come only after adding.\"}]}}</lesson-step>", "source_refs": [{"source_id": "src-d8b8f95610afc5a333373a34", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-2"}, {"source_id": "sr