INSERT INTO "documents" VALUES('streams','reply:cross-term:3286df26-3096-41b2-bd0f-d55c162b0e48','{"record_user": true, "id": "reply:cross-term:3286df26-3096-41b2-bd0f-d55c162b0e48", "concept_id": "paths", "prompt": "And when both amplitudes are real?", "channel": "sidequestion", "language": "en", "source_refs": [{"source_id": "src-d8b8f95610afc5a333373a34", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-2"}, {"source_id": "src-d8b8f95610afc5a333373a34", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-3"}, {"source_id": "src-d8b8f95610afc5a333373a34", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-4"}], "prompt_snapshot": {"context": {"concept": {"id": "paths", "title": "Adding path amplitudes", "objective": "Predict interference from two amplitudes", "links": [{"source_id": "src-d8b8f95610afc5a333373a34", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-2"}, {"source_id": "src-d8b8f95610afc5a333373a34", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-3"}, {"source_id": "src-d8b8f95610afc5a333373a34", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-4"}], "exercises": [{"source_id": "src-d8b8f95610afc5a333373a34", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-4", "question": "Find the probability for equal amplitudes.", "required_concepts": ["paths"]}]}, "chapter": {"id": "superposition", "title": "Superposition", "concept_ids": ["paths", "states"], "index": 0, "total": 2}, "position": {"concept_id": "paths", "goal": "Predict interference", "next_step": "Start the lesson", "progress": ""}, "prerequisites": [], "next_concept_id": "states", "sources": [{"source_id": "src-d8b8f95610afc5a333373a34", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-2", "id": "line-2", "locator": {"line": 2}, "text": "Two paths reach the same detector, each with a complex amplitude.", "stale": false}, {"source_id": "src-d8b8f95610afc5a333373a34", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-3", "id": "line-3", "locator": {"line": 3}, "text": "The total amplitude is the sum of the path amplitudes.", "stale": false}, {"source_id": "src-d8b8f95610afc5a333373a34", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-4", "id": "line-4", "locator": {"line": 4}, "text": "The probability is the squared magnitude of the total amplitude.", "stale": false}]}, "route": [{"id": "paths", "title": "Adding path amplitudes"}, {"id": "states", "title": "States and global phase", "prerequisites": ["paths"]}, {"id": "outcomes", "title": "Measurement outcomes", "prerequisites": ["states"]}], "session": {"position": {"concept_id": "paths", "goal": "Predict interference", "next_step": "Start the lesson", "progress": ""}, "active_branch": null, "due_explanations": [], "unanswered_questions": [], "recent_interactions": [{"id": "stream:c7865339-0a1a-45cb-bb1e-e8a42d53eed6", "role": "assistant", "text": "## Path amplitudes\n\nEach path carries a complex amplitude $a$ or $b$.\n<course-memory>{\"entries\": [{\"kind\": \"taught_term\", \"text\": \"amplitude\"}, {\"kind\": \"preference\", \"text\": \"Short steps with one formula each\"}], \"cleared\": []}</course-memory>\n<lesson-step>{\"title\": \"Path amplitudes\", \"remaining\": [{\"title\": \"Adding amplitudes\"}], \"check\": {\"idea\": \"What does a path carry?\", \"question\": \"What does a path carry?\", \"correct\": 0, \"options\": [{\"text\": \"A complex amplitude\", \"explanation\": \"Each path contributes an amplitude.\"}, {\"text\": \"A probability\", \"explanation\": \"Probabilities come only after adding.\"}]}}</lesson-step>", "concept_id": "paths", "supplied_source_refs": [{"source_id": "src-d8b8f95610afc5a333373a34", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-2"}, {"source_id": "src-d8b8f95610afc5a333373a34", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-3"}, {"source_id": "src-d8b8f95610afc5a333373a34", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-4"}], "source_refs": [{"source_id": "src-d8b8f95610afc5a333373a34", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-2"}, {"source_id": "src-d8b8f95610afc5a333373a34", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-3"}, {"source_id": "src-d8b8f95610afc5a333373a34", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-4"}], "source_context_concept_id": "paths", "sequence": 2}, {"id": "check-answer:c7865339-0a1a-45cb-bb1e-e8a42d53eed6", "role": "user", "text": "Check question: What does a path carry?\nAnswer: A probability", "concept_id": "paths", "kind": "check_answer", "supplied_source_refs": [], "source_refs": [], "source_context_concept_id": "paths", "sequence": 3}, {"id": "stream-user:step:44a01d0f-d419-48cc-8a06-d32a19f065f1", "role": "user", "text": "Continue with the next step.", "concept_id": "paths", "source_refs": [{"source_id": "src-d8b8f95610afc5a333373a34", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-2"}, {"source_id": "src-d8b8f95610afc5a333373a34", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-3"}, {"source_id": "src-d8b8f95610afc5a333373a34", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-4"}], "source_context_concept_id": "paths", "sequence": 4}, {"id": "stream:step:44a01d0f-d419-48cc-8a06-d32a19f065f1", "role": "assistant", "text": "## Adding amplitudes\n\n$$P = |a + b|^2 = |a|^2 + |b|^2 + 2\\,\\mathrm{Re}(a^* b)$$\n<course-memory>{\"entries\": [{\"kind\": \"taught_term\", \"text\": \"interference term\"}], \"cleared\": []}</course-memory>\n<lesson-step>{\"remaining\": []}</lesson-step>", "concept_id": "paths", "supplied_source_refs": [{"source_id": "src-d8b8f95610afc5a333373a34", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-2"}, {"source_id": "src-d8b8f95610afc5a333373a34", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-3"}, {"source_id": "src-d8b8f95610afc5a333373a34", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-4"}], "source_refs": [{"source_id": "src-d8b8f95610afc5a333373a34", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-2"}, {"source_id": "src-d8b8f95610afc5a333373a34", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-3"}, {"source_id": "src-d8b8f95610afc5a333373a34", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-4"}], "source_context_concept_id": "paths", "sequence": 5}, {"id": "stream:practice-04dcb662-04b2-4ff7-bdea-00b860709358", "role": "assistant", "text": "{\"questions\": [{\"question\": \"Two paths have amplitudes $1/2$ and $e^{i\\\\phi}/2$.\", \"parts\": [{\"label\": \"(a)\", \"text\": \"Find $P(\\\\phi)$.\"}, {\"label\": \"(b)\", \"text\": \"When is it zero?\"}], \"origin\": \"self_created\", \"source_refs\": []}]}", "concept_id": "paths", "supplied_source_refs": [{"source_id": "src-d8b8f95610afc5a333373a34", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-2"}, {"source_id": "src-d8b8f95610afc5a333373a34", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-3"}, {"source_id": "src-d8b8f95610afc5a333373a34", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-4"}], "source_refs": [{"source_id": "src-d8b8f95610afc5a333373a34", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-2"}, {"source_id": "src-d8b8f95610afc5a333373a34", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-3"}, {"source_id": "src-d8b8f95610afc5a333373a34", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-4"}], "source_context_concept_id": "paths", "sequence": 6}, {"id": "stream-user:branch:cross-term", "role": "user", "text": "Why is the cross term 2 Re(a* b)?", "concept_id": "paths", "source_refs": [{"source_id": "src-d8b8f95610afc5a333373a34", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-2"}, {"source_id": "src-d8b8f95610afc5a333373a34", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-3"}, {"source_id": "src-d8b8f95610afc5a333373a34", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-4"}], "source_context_concept_id": "paths", "sequence": 7}, {"id": "stream:branch:cross-term", "role": "assistant", "text": "Because $|z|^2 = z^* z$, the cross terms give $2\\,\\mathrm{Re}(a^* b)$.\n<teaching-decision>{\"depth\": \"short\", \"category\": \"local\", \"rationale\": \"Local algebra\", \"suggest_supplement\": false, \"supplement_goal\": \"\"}</teaching-decision>\n<course-memory>{\"entries\": [{\"kind\": \"taught_term\", \"text\": \"complex conjugate\"}], \"cleared\": []}</course-memory>", "concept_id": "paths", "supplied_source_refs": [{"source_id": "src-d8b8f95610afc5a333373a34", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-2"}, {"source_id": "src-d8b8f95610afc5a3